import{_ as e,o,c as r,a2 as t}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"常见问题","description":"AgoraIn v4 登录、激活、扫卡、阅卷、AI 与存储的排查入口","frontmatter":{"title":"常见问题","description":"AgoraIn v4 登录、激活、扫卡、阅卷、AI 与存储的排查入口"},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1791168527000}'),d={name:"faq.md"};function n(i,a,l,h,c,s){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="账号与激活" tabindex="-1">账号与激活 <a class="header-anchor" href="#账号与激活" aria-label="Permalink to &quot;账号与激活&quot;">​</a></h2><h3 id="登录后约-1-秒提示「登录已过期」并跳回登录页" tabindex="-1">登录后约 1 秒提示「登录已过期」并跳回登录页 <a class="header-anchor" href="#登录后约-1-秒提示「登录已过期」并跳回登录页" aria-label="Permalink to &quot;登录后约 1 秒提示「登录已过期」并跳回登录页&quot;">​</a></h3><p>服务端签发的令牌必须是合法 JWS（恰好两个点）。若服务端日志出现 <code>IDX14122: JWT is not a well formed JWE, there are more than four dots</code>， 说明令牌生成方式不对：应使用 <code>JsonWebTokenHandler().CreateToken(...)</code>， 而不是 <code>new JwtSecurityToken(...).ToString()</code>（后者在新版本库中返回调试字符串）。</p><p>快速自检：登录拿到 token 后 <code>tr -cd &#39;.&#39; | wc -c</code> 数点数，<strong>合法 JWS 恰好 2 个</strong>。</p><h3 id="区域未激活-成员登录不了" tabindex="-1">区域未激活，成员登录不了 <a class="header-anchor" href="#区域未激活-成员登录不了" aria-label="Permalink to &quot;区域未激活，成员登录不了&quot;">​</a></h3><p>未激活区域<strong>仅主账号可登录</strong>，其余成员被拒绝，且受控功能全部停用。请主账号在 「授权管理」页输入平台方颁发的 <strong>AGRR- 激活码</strong>完成激活或续期。</p><h3 id="忘记管理员密码" tabindex="-1">忘记管理员密码 <a class="header-anchor" href="#忘记管理员密码" aria-label="Permalink to &quot;忘记管理员密码&quot;">​</a></h3><p>在登录页选择「忘记密码」，通过邮箱验证码重置（需服务端已配置 SMTP）。</p><h2 id="管理面板" tabindex="-1">管理面板 <a class="header-anchor" href="#管理面板" aria-label="Permalink to &quot;管理面板&quot;">​</a></h2><h3 id="打开某个页面提示-404-例如-license" tabindex="-1">打开某个页面提示 404（例如 <code>/license</code>） <a class="header-anchor" href="#打开某个页面提示-404-例如-license" aria-label="Permalink to &quot;打开某个页面提示 404（例如 `/license`）&quot;">​</a></h3><p>管理面板是 history 路由 SPA，反向代理需要回退到 <code>index.html</code>。宝塔/nginx 里若有安全规则拦截 <code>LICENSE</code>、<code>README.md</code> 等关键词（<strong>大小写不敏感</strong>），会误伤 <code>/license</code> 路由；把 SPA 路由块放到 安全规则<strong>之前</strong>即可，详见 <a href="/deploy.html">部署指南</a>。</p><h3 id="页面改了但浏览器里还是旧的" tabindex="-1">页面改了但浏览器里还是旧的 <a class="header-anchor" href="#页面改了但浏览器里还是旧的" aria-label="Permalink to &quot;页面改了但浏览器里还是旧的&quot;">​</a></h3><p>管理面板内置过期自愈：启动时会比对线上资源 hash，发现不一致则提示并自动刷新。 若仍异常，请 <code>Ctrl + F5</code> 强刷一次（旧标签页内存里永远是被加载时的旧 JS）。</p><h3 id="点了「下载-导出」没有反应或提示无权限" tabindex="-1">点了「下载 / 导出」没有反应或提示无权限 <a class="header-anchor" href="#点了「下载-导出」没有反应或提示无权限" aria-label="Permalink to &quot;点了「下载 / 导出」没有反应或提示无权限&quot;">​</a></h3><p>下载类接口在<strong>新标签页</strong>中无法携带 <code>Authorization</code> 头，前端会自动把令牌拼到下载地址上 （<code>?token=</code>）。若代理或网关剥离了查询串，请检查反向代理配置。答题卡打印页是匿名接口， 带 <code>?download=1</code> 会直接触发附件下载。</p><h2 id="扫卡与答题卡" tabindex="-1">扫卡与答题卡 <a class="header-anchor" href="#扫卡与答题卡" aria-label="Permalink to &quot;扫卡与答题卡&quot;">​</a></h2><h3 id="扫卡提示「摄像头打开失败」" tabindex="-1">扫卡提示「摄像头打开失败」 <a class="header-anchor" href="#扫卡提示「摄像头打开失败」" aria-label="Permalink to &quot;扫卡提示「摄像头打开失败」&quot;">​</a></h3><ol><li>先看页面上的错误名：<code>NotAllowedError</code> = 权限未授予，<code>NotReadableError</code> = 设备被占用/推不出帧</li><li>手机 App 内嵌页面需要宿主 WebView 把相机权限回调转发给网页（MAUI 侧需在 <code>WebViewHandler.Mapper.AppendToMapping</code> 中装回授权 Client）</li><li>网页端动态扫卡按屏幕方向记住可用分辨率档位，切换屏幕方向后会自动重开摄像头</li></ol><h3 id="扫卡「切图失败」或总显示第一页" tabindex="-1">扫卡「切图失败」或总显示第一页 <a class="header-anchor" href="#扫卡「切图失败」或总显示第一页" aria-label="Permalink to &quot;扫卡「切图失败」或总显示第一页&quot;">​</a></h3><p>服务端会按<strong>页码框 → 二维码 → 落盘文件名 → 版面环匹配</strong>的顺序判定页序， 只有客观题页才参与版面校验。请确认：打印时<strong>未被缩放</strong>（100% 原始尺寸）、 页面四角定位标记完整、纸型与后台配置一致。</p><h3 id="答题卡打印后跨页错位-页码标记跑到别页" tabindex="-1">答题卡打印后跨页错位 / 页码标记跑到别页 <a class="header-anchor" href="#答题卡打印后跨页错位-页码标记跑到别页" aria-label="Permalink to &quot;答题卡打印后跨页错位 / 页码标记跑到别页&quot;">​</a></h3><p>必须使用<strong>服务端精确分页</strong>的答卷：每张物理页是固定高度容器（277mm）且自带定位标记与页脚。 打印时关闭浏览器自带的「页眉页脚」，缩放选择 100%，纸张与后台配置的纸型一致。</p><h2 id="阅卷与出分" tabindex="-1">阅卷与出分 <a class="header-anchor" href="#阅卷与出分" aria-label="Permalink to &quot;阅卷与出分&quot;">​</a></h2><h3 id="上传后一直没出结果" tabindex="-1">上传后一直没出结果 <a class="header-anchor" href="#上传后一直没出结果" aria-label="Permalink to &quot;上传后一直没出结果&quot;">​</a></h3><p>长耗时的识别任务在服务端后台执行（HTTP 立即返回 202，前端轮询结果）。可在 「AI 设置 → 调用日志」查看每次调用的状态、耗时与原始响应。</p><h3 id="ai-批改结果为空或-json-解析失败" tabindex="-1">AI 批改结果为空或 JSON 解析失败 <a class="header-anchor" href="#ai-批改结果为空或-json-解析失败" aria-label="Permalink to &quot;AI 批改结果为空或 JSON 解析失败&quot;">​</a></h3><p>推理型模型（DeepSeek-R1 / Mimo 等）会先输出思考过程，容易顶满 <code>max_tokens</code> 被截断。 平台已做三层处理：提示词要求直接输出 JSON、返回内容做<strong>去思考区与括号配对提取</strong>、 以及解析失败自动追问一次。若仍频繁失败，可降低单次图片数量（分批识别）或改用更强的视觉模型。</p><h3 id="客观题判分与预期不一致" tabindex="-1">客观题判分与预期不一致 <a class="header-anchor" href="#客观题判分与预期不一致" aria-label="Permalink to &quot;客观题判分与预期不一致&quot;">​</a></h3><p>客观题以<strong>本地涂卡识别</strong>结果为准（零 token）。若答题卡被旋转、缩放或涂抹过浅，识别会失败并 转人工。可在后台把该题设为「教师手判」。</p><h3 id="ai-提示「额度不足」" tabindex="-1">AI 提示「额度不足」 <a class="header-anchor" href="#ai-提示「额度不足」" aria-label="Permalink to &quot;AI 提示「额度不足」&quot;">​</a></h3><p>机构使用平台 AI 时按 token 扣减额度（余额以人民币计价）。请在「AI 设置」页兑换 <strong>AGRT- 额度码</strong>；机构自配 API 密钥则不受额度限制。</p><h2 id="数据与存储" tabindex="-1">数据与存储 <a class="header-anchor" href="#数据与存储" aria-label="Permalink to &quot;数据与存储&quot;">​</a></h2><h3 id="服务端启动报-sqlite-error-14-unable-to-open-database-file" tabindex="-1">服务端启动报 <code>SQLite Error 14: unable to open database file</code> <a class="header-anchor" href="#服务端启动报-sqlite-error-14-unable-to-open-database-file" aria-label="Permalink to &quot;服务端启动报 `SQLite Error 14: unable to open database file`&quot;">​</a></h3><p>数据库文件所在目录不存在或不可写。SQLite 只创建文件不创建目录， 请 <code>mkdir -p &lt;程序目录&gt;/data &amp;&amp; chown -R www:www &lt;程序目录&gt;/data</code> （或在 <code>appsettings.json</code> 的 <code>Data:Directory</code> 指定其它可写目录）。</p><h3 id="远程存储怎么工作的-会不会丢文件" tabindex="-1">远程存储怎么工作的？会不会丢文件 <a class="header-anchor" href="#远程存储怎么工作的-会不会丢文件" aria-label="Permalink to &quot;远程存储怎么工作的？会不会丢文件&quot;">​</a></h3><p>答题卡原图与教学资料使用 <strong>AES-256-GCM</strong> 认证加密后上传 WebDAV 远程磁盘，按区域分目录； 服务器只保留 LRU 缓存，且<strong>只淘汰已确认上传成功</strong>的本机副本，远程不可用时排队补传。</p><h3 id="关闭-ai-图像外发后会发生什么" tabindex="-1">关闭 AI 图像外发后会发生什么 <a class="header-anchor" href="#关闭-ai-图像外发后会发生什么" aria-label="Permalink to &quot;关闭 AI 图像外发后会发生什么&quot;">​</a></h3><p>关闭后，平台<strong>不会</strong>向任何第三方大模型发送作答图像：客观题仍由本地识别判分， 主观题转为教师人工批改（或使用本地识别能力）。该开关在「AI 设置」中按机构控制。</p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><h3 id="桌面端在-windows-10-上启动即报错" tabindex="-1">桌面端在 Windows 10 上启动即报错 <a class="header-anchor" href="#桌面端在-windows-10-上启动即报错" aria-label="Permalink to &quot;桌面端在 Windows 10 上启动即报错&quot;">​</a></h3><p>.NET 10 在部分 Windows 10 上默认 CET 检查会致命报错，v4 已统一设置 <code>CETCompat=false</code>， 请使用官方发布包（自包含）运行。</p><h3 id="一体机插件收不到呼叫-课表" tabindex="-1">一体机插件收不到呼叫 / 课表 <a class="header-anchor" href="#一体机插件收不到呼叫-课表" aria-label="Permalink to &quot;一体机插件收不到呼叫 / 课表&quot;">​</a></h3><p>插件接口为 <code>api/calls_register</code>、<code>api/calls_pull</code>、<code>api/calls_ack</code> 与 <code>api/profile_pull</code> （无 <code>/v4</code> 前缀，密码鉴权）。课表推送后，插件需升级到支持 <code>profile_pull</code> 的版本才会消费服务器档案。 详见<a href="/plugin.html">一体机联动</a>。</p><h3 id="想回到旧版本" tabindex="-1">想回到旧版本 <a class="header-anchor" href="#想回到旧版本" aria-label="Permalink to &quot;想回到旧版本&quot;">​</a></h3><p>v3.2 及更早版本的文档已归档：<a href="/v3.2/">v3.2</a> · <a href="/v2.8/">v2.8</a> · <a href="/v2.7/">v2.7</a>。 注意 v4 与旧版本的数据结构不同，升级前请备份 <code>data/</code> 目录。</p><h2 id="还有问题" tabindex="-1">还有问题？ <a class="header-anchor" href="#还有问题" aria-label="Permalink to &quot;还有问题？&quot;">​</a></h2><p>请附上：<strong>页面截图 + 服务端日志对应时间片段 + 操作步骤</strong>。 运维排查入口依次是：<code>/api/v4/setup/status</code> 健康检查 → 服务端日志 → AI 调用日志。</p>',48)])])}const b=e(d,[["render",n]]);export{u as __pageData,b as default};
